        ("arima-model", "/əˈriːmə ˌmɒdl/", "n", "mô hình tự hồi quy tích hợp trung bình trượt (ARIMA)", "Autoregressive Integrated Moving Average, a statistical analysis model used to predict future trends in time-series", "An ARIMA-model captured seasonal fluctuations in quarterly airline passenger bookings accurately.", "Mô hình ARIMA đã nắm bắt chính xác các dao động theo mùa trong lượng đặt vé máy bay hàng quý.", ["time-series ARIMA"], ["fit an ARIMA-model"], "Autoregressive Integrated Moving Average"),
        ("anomaly-detection", "/əˈnɒməli dɪˌtɛkʃən/", "n", "phát hiện bất thường và sai lệch trong luồng dữ liệu", "the identification of rare events or observations which deviate significantly from expected normal behavior", "Real-time anomaly-detection triggered alerts when server CPU temperatures suddenly breached ninety degrees.", "Hệ thống phát hiện bất thường thời gian thực đã cảnh báo khi nhiệt độ CPU máy chủ đột ngột vượt quá 90 độ.", ["deviation finding"], ["real-time anomaly-detection"], "Detecting anomalies in behavior"),
        ("correlation-matrix", "/ˌkɒrəˈleɪʃən ˌmeɪtrɪks/", "n", "ma trận tương quan đo mối quan hệ giữa các biến", "a table showing correlation coefficients between sets of variables, highlighting mutual linear relationships", "A heatmap of the correlation-matrix revealed strong multicollinearity between advertising spend and sales volume.", "Bản đồ nhiệt ma trận tương quan đã cho thấy sự cộng tuyến đa biến mạnh mẽ giữa chi tiêu quảng cáo và doanh số.", ["correlation table"], ["plot correlation-matrix"], "Matrix of pairwise correlation values"),
        ("p-value-significance", "/ˌpiː ˈvæljuː sɪɡˌnɪfɪkəns/", "n", "mức ý nghĩa thống kê của giá trị p", "the probability of obtaining test results at least as extreme as the observed results, assuming the null hypothesis is true", "A p-value below 0.01 established high statistical significance, disproving the placebo hypothesis.", "Giá trị p dưới 0,01 đã xác lập mức ý nghĩa thống kê cao, bác bỏ giả thuyết về hiệu ứng giả dược.", ["statistical significance"], ["test for p-value-significance"], "Value of statistical probability P"),
        ("null-hypothesis", "/ˌnʌl haɪˈpɒθəsɪs/", "n", "giả thuyết vô hiệu (giả định không có sự khác biệt)", "a general statement or default position that there is no relationship between two measured phenomena", "Experimental researchers aim to reject the null-hypothesis with rigorous empirical evidence.", "Các nhà nghiên cứu thực nghiệm hướng đến việc bác bỏ giả thuyết vô hiệu bằng các bằng chứng thực nghiệm chặt chẽ.", ["H0 default assumption"], ["reject the null-hypothesis"], "Hypothesis of null/zero difference"),
        ("confidence-interval", "/ˈkɒnfɪdəns ˌɪntərvl/", "n", "khoảng tin cậy chứa giá trị thực với xác suất xác định", "a range of values so defined that there is a specified probability that the value of a parameter lies within it", "The poll reported a ninety-five percent confidence-interval of forty-eight to fifty-two percent voter support.", "Cuộc thăm dò đã báo cáo khoảng tin cậy 95% từ 48% đến 52% mức độ ủng hộ của cử tri.", ["margin of certainty"], ["calculate confidence-interval"], "Interval of statistical confidence"),
        ("bayesian-inference", "/ˌbeɪziən ˈɪnfərəns/", "n", "suy luận thống kê Bayes cập nhật xác suất theo dữ liệu mới", "a method of statistical inference in which Bayes' theorem is used to update the probability for a hypothesis as more evidence arrives", "Bayesian-inference continuously updates spam filter parameters as users flag new phishing emails.", "Suy luận Bayes liên tục cập nhật các tham số lọc thư rác khi người dùng gắn cờ các email lừa đảo mới.", ["probabilistic updating"], ["apply Bayesian-inference"], "Thomas Bayes probability updating theorem"),
        ("monte-carlo-simulation", "/ˌmɒnti ˈkɑːrloʊ ˌsɪmjʊˈleɪʃən/", "n", "mô phỏng Monte Carlo bằng phương pháp lấy mẫu ngẫu nhiên", "a mathematical technique that uses repeated random sampling to obtain numerical results for complex non-deterministic problems", "Financial risk analysts ran ten thousand Monte-Carlo-simulations to estimate retirement portfolio longevity.", "Các nhà phân tích rủi ro tài chính đã chạy 10.000 lần mô phỏng Monte Carlo để ước tính tuổi thọ danh mục đầu tư hưu trí.", ["stochastic simulation"], ["run a Monte-Carlo-simulation"], "Named after the gambling resort Monte Carlo"),
        ("a-b-testing", "/ˌeɪ ˈbiː ˌtɛstɪŋ/", "n", "thử nghiệm A/B so sánh hai phiên bản giao diện hoặc thuật toán", "a randomized experimentation process wherein two or more versions of a variable are shown to users to determine which performs better", "A rigorous four-week A/B-testing confirmed that the green checkout button improved conversions by two percent.", "Thử nghiệm A/B nghiêm ngặt kéo dài 4 tuần đã xác nhận rằng nút thanh toán màu xanh lá giúp cải thiện tỷ lệ chuyển đổi thêm 2%.", ["split testing"], ["conduct A/B-testing"], "Testing variant A versus variant B"),
        ("data-visualization", "/ˈdeɪtə ˌvɪʒwəlaɪˈzeɪʃən/", "n", "trực quan hóa dữ liệu qua biểu đồ đồ họa", "the graphical representation of information and data using visual elements like charts, graphs, and interactive maps", "Effective data-visualization transforms complex multi-dimensional metrics into intuitive executive dashboards.", "Trực quan hóa dữ liệu hiệu quả giúp biến đổi các chỉ số đa chiều phức tạp thành các bảng điều khiển trực quan cho ban lãnh đạo.", ["graphical charting"], ["master data-visualization"], "Visualizing data insights through charts"),
        ("predictive-analytics-modeling", "/prɪˌdɪktɪv ænəˈlɪtɪks ˈmɒdəlɪŋ/", "n", "mô hình hóa phân tích dự đoán xu hướng tương lai", "the practice of extracting information from existing data sets in order to determine patterns and predict future outcomes", "Actuaries utilize predictive-analytics-modeling to calculate life insurance risk profiles.", "Các chuyên viên định phí bảo hiểm sử dụng mô hình phân tích dự đoán để tính toán hồ sơ rủi ro bảo hiểm nhân thọ.", ["predictive modeling"], ["implement predictive-analytics-modeling"], "Predicting outcomes via analytical models"),
        ("unsupervised-learning-algorithm", "/ʌnˈsuːpərvaɪzd ˈlɜːrnɪŋ ˈælɡərɪðəm/", "n", "thuật toán học không giám sát tự tìm quy luật ẩn", "a type of algorithm that learns patterns from untagged data without human guidance or pre-existing labels", "Clustering algorithms are classic examples of unsupervised-learning-algorithms discovering hidden customer groupings.", "Các thuật toán phân cụm là ví dụ điển hình của thuật toán học không giám sát giúp phát hiện các nhóm khách hàng tiềm ẩn.", ["unsupervised learning"], ["train unsupervised-learning-algorithm"], "Learning without labeled supervision"),
